  @Test
  void initializesAesGcmMetadataAndCombinesStoredPrefixWithFileUniqueValue() throws Exception {
    byte[] prefix = new byte[] {1, 2, 3};
    byte[] fileUnique = new byte[] {4, 5, 6, 7};
    byte[] key = new byte[16];

    EncryptionAlgorithm algorithm = EncryptionAlgorithm.AES_GCM_V1(new AesGcmV1());
    algorithm.getAES_GCM_V1().setAad_file_unique(fileUnique);
    algorithm.getAES_GCM_V1().setAad_prefix(prefix);
    algorithm.getAES_GCM_V1().setSupply_aad_prefix(false);

    DecryptionKeyRetriever retriever = metadata -> key;
    FileDecryptionProperties properties = FileDecryptionProperties.builder()
        .withAADPrefix(prefix)
        .withKeyRetriever(retriever)
        .withoutFooterSignatureVerification()
        .build();

    org.apache.parquet.crypto.InternalFileDecryptor decryptor =
        new org.apache.parquet.crypto.InternalFileDecryptor(properties);

    decryptor.setFileCryptoMetaData(algorithm, false, new byte[] {9});

    assertEquals(true, field(decryptor, "fileCryptoMetaDataProcessed"));
    assertSame(algorithm, field(decryptor, "algorithm"));
    assertArrayEquals(new byte[] {1, 2, 3, 4, 5, 6, 7}, field(decryptor, "fileAAD"));
    assertArrayEquals(key, field(decryptor, "footerKey"));
  }

  @Test
  void supportsAesGcmCtrAndUsesFileUniqueValueWithoutPrefix() throws Exception {
    byte[] fileUnique = new byte[] {8, 9, 10};

    EncryptionAlgorithm algorithm =
        EncryptionAlgorithm.AES_GCM_CTR_V1(new AesGcmCtrV1());
    algorithm.getAES_GCM_CTR_V1().setAad_file_unique(fileUnique);
