        .withoutFooterSignatureVerification()
        .build();

    org.apache.parquet.crypto.InternalFileDecryptor decryptor =
        new org.apache.parquet.crypto.InternalFileDecryptor(properties);

    decryptor.setFileCryptoMetaData(algorithm, false, null);

    assertArrayEquals(fileUnique, field(decryptor, "fileAAD"));
  }

  @Test
  void retrievesFooterKeyUsingSuppliedMetadata() throws Exception {
    byte[] metadata = new byte[] {11, 12};
    byte[] key = new byte[16];
    AtomicInteger calls = new AtomicInteger();

    DecryptionKeyRetriever retriever = supplied -> {
      calls.incrementAndGet();
      assertArrayEquals(metadata, supplied);
      return key;
    };

    EncryptionAlgorithm algorithm = algorithmWithoutPrefix(new byte[] {1});
    FileDecryptionProperties properties = FileDecryptionProperties.builder()
        .withKeyRetriever(retriever)
        .withoutFooterSignatureVerification()
        .build();

    org.apache.parquet.crypto.InternalFileDecryptor decryptor =
        new org.apache.parquet.crypto.InternalFileDecryptor(properties);

    decryptor.setFileCryptoMetaData(algorithm, true, metadata);

    assertEquals(1, calls.get());
    assertArrayEquals(key, field(decryptor, "footerKey"));
