  }

  @Test
  void rejectsMissingRequiredExternalPrefix() {
    EncryptionAlgorithm algorithm = EncryptionAlgorithm.AES_GCM_V1(new AesGcmV1());
    algorithm.getAES_GCM_V1().setAad_file_unique(new byte[] {1});
    algorithm.getAES_GCM_V1().setSupply_aad_prefix(true);

    FileDecryptionProperties properties = FileDecryptionProperties.builder()
        .withKeyRetriever(ignored -> new byte[16])
        .withoutFooterSignatureVerification()
        .build();

    org.apache.parquet.crypto.InternalFileDecryptor decryptor =
        new org.apache.parquet.crypto.InternalFileDecryptor(properties);

    assertThrows(
        ParquetCryptoRuntimeException.class,
        () -> decryptor.setFileCryptoMetaData(algorithm, false, null));
  }

  @Test
  void rejectsMismatchedPrefixFromFileAndProperties() {
    EncryptionAlgorithm algorithm = EncryptionAlgorithm.AES_GCM_V1(new AesGcmV1());
    algorithm.getAES_GCM_V1().setAad_file_unique(new byte[] {1});
    algorithm.getAES_GCM_V1().setAad_prefix(new byte[] {1, 2});
    algorithm.getAES_GCM_V1().setSupply_aad_prefix(false);

    FileDecryptionProperties properties = FileDecryptionProperties.builder()
        .withAADPrefix(new byte[] {9, 9})
        .withKeyRetriever(ignored -> new byte[16])
        .withoutFooterSignatureVerification()
        .build();

    org.apache.parquet.crypto.InternalFileDecryptor decryptor =
        new org.apache.parquet.crypto.InternalFileDecryptor(properties);

    assertThrows(
        ParquetCryptoRuntimeException.class,
        () -> decryptor.setFileCryptoMetaData(algorithm, false, null));
  }

  @Test
  void rejectsUnexpectedPrefixWhenFileDoesNotUseOne() {
    EncryptionAlgorithm algorithm = algorithmWithoutPrefix(new byte[] {1});

    FileDecryptionProperties properties = FileDecryptionProperties.builder()
        .withAADPrefix(new byte[] {5})
        .withKeyRetriever(ignored -> new byte[16])
        .withoutFooterSignatureVerification()
        .build();

    org.apache.parquet.crypto.InternalFileDecryptor decryptor =
        new org.apache.parquet.crypto.InternalFileDecryptor(properties);

    assertThrows(
        ParquetCryptoRuntimeException.class,
        () -> decryptor.setFileCryptoMetaData(algorithm, false, null));
  }

  @Test
  void rejectsNullKeyReturnedByRetriever() {
    EncryptionAlgorithm algorithm = algorithmWithoutPrefix(new byte[] {1});

    FileDecryptionProperties properties = FileDecryptionProperties.builder()
        .withKeyRetriever(ignored -> null)
        .withoutFooterSignatureVerification()
        .build();

    org.apache.parquet.crypto.InternalFileDecryptor decryptor =
        new org.apache.parquet.crypto.InternalFileDecryptor(properties);

    assertThrows(
        ParquetCryptoRuntimeException.class,
        () -> decryptor.setFileCryptoMetaData(algorithm, true, new byte[] {1}));
  }

  @Test
  void wrapsKeyAccessDeniedWithFooterContext() {
    EncryptionAlgorithm algorithm = algorithmWithoutPrefix(new byte[] {1});
    KeyAccessDeniedException denied = new KeyAccessDeniedException("denied");

    FileDecryptionProperties properties = FileDecryptionProperties.builder()
        .withKeyRetriever(ignored -> {
          throw denied;
        })
        .withoutFooterSignatureVerification()
        .build();

    org.apache.parquet.crypto.InternalFileDecryptor decryptor =
        new org.apache.parquet.crypto.InternalFileDecryptor(properties);

    KeyAccessDeniedException thrown = assertThrows(
        KeyAccessDeniedException.class,
        () -> decryptor.setFileCryptoMetaData(algorithm, true, new byte[] {1}));

    assertEquals("Footer key: access denied", thrown.getMessage());
    assertSame(denied, thrown.getCause());
  }

  private static EncryptionAlgorithm algorithmWithoutPrefix(byte[] fileUnique) {
    EncryptionAlgorithm algorithm = ParquetCipher.AES_GCM_V1.getEncryptionAlgorithm();
    algorithm.getAES_GCM_V1().setAad_file_unique(fileUnique);
    algorithm.getAES_GCM_V1().setSupply_aad_prefix(false);
    return algorithm;
